    imageCaption: 'NOVA FilarmÃ³nica durante su concierto inaugural en Cochabamba. Foto: NOVA FilarmÃ³nica / Los Tiempos',
    categoryEs: 'MÃºsica',
    categoryEn: 'Music',
    enableComments: true,
    featured: true,
    views: 1087,
    source: 'Los Tiempos',
