        imageUrl: '/images/news/2026-08-13-frontera-segura.jpg',
        imageCaption: 'PolicÃ­as de Bolivia y Brasil participarÃ¡n del programa binacional Frontera Segura en GuayaramerÃ­n. Imagen: ANF',
        categoryEs: 'Seguridad',
        categoryEn: 'Public Safety',
        enableComments: true,
        featured: true,
        breaking: true,
        views: 1,
        location: 'GuayaramerÃ­n, Beni',
        source: 'ANF',
        region: 'Bolivia',
        sourceUrl: 'https://www.noticiasfides.com/nacional/seguridad/las-policias-de-bolivia-y-brasil-lanzaran-el-jueves-el-programa-frontera-segura'
