        readTimeEs: '4 min de lectura',
        readTimeEn: '3 min read',
        imageUrl: '/images/blog/bolivia-17-agosto-2026/sucre-mordeduras-perros-2500-casos.webp',
        imageCaption: 'Mordeduras de perros en Sucre: hasta 10 casos diarios en la capital. Imagen: Bolivia TV / Notibol',
        categoryEs: 'Salud',
        categoryEn: 'Health',
        enableComments: true,
        featured: false,
        breaking: false,
        views: 1,
        location: 'Sucre, Chuquisaca, Bolivia',
        source: 'Bolivia TV',
        region: 'Bolivia',
        sourceUrl: 'https://notibol.com/noticia/bo/6a825bfcb4e43/sucre-registra-hasta-10-mordeduras-de-perros-al-dia-reportan-mas-de-2500-casos-en-chuquisaca'
